[
  {
    "hindi": "त्व सहित व्यवस्था",
    "hinglish": "tva sahit vyavastha",
    "pageno": 83,
    "paribhasha": [
      "मानवीयता पूर्ण आचरण सहित सार्वभौम व्यवस्था में भागीदारी।",
      "प्रत्येक एक में धर्म एवं स्वभाव सहज प्रकाशन।"
    ]
  },
  {
    "hindi": "न्यायपूर्ण व्यवस्था",
    "hinglish": "nyaypurn vyavastha",
    "pageno": 104,
    "paribhasha": [
      "मानवीयता के संरक्षण एवं संवर्धन के लिए नैतिकता पूर्वक चारों आयामों एवं पाँचो स्थितियों में निर्विषमता तथा सभ्यता, संस्कृति, विधि, व्यवस्था की एकात्मता।",
      "चार आयाम - विचार, व्यवहार, व्यवसाय, अनुभव। पाँच स्थिति - व्यक्ति, परिवार, समाज, राष्ट्र, अंतर्राष्ट्र।"
    ]
  },
  {
    "hindi": "परिवार मूलक स्वराज्य व्यवस्था",
    "hinglish": "parivar mulak svarajya vyavastha",
    "pageno": 112,
    "paribhasha": [
      "जागृत मानव परिवार में कम से कम दस व्यक्तियों का होना स्वीकार होता है। ऐसे परिवार में से एक व्यक्ति को व्यवस्था के लोकव्यापीकरण करने के उद्देश्य से दस व्यक्ति निर्वाचित करते हैं स्वयं भी अपने को निर्वाचित कर लेता है इस प्रकार दस व्यक्तियों में से एक व्यक्ति व्यवस्था में भागीदारी करने के लिए तैयारी करता है। यही प्रथम जन प्रतिनिधि सभा है। इसी प्रकार से पूरे गाँव में, पूरे देश में, पूरे विश्व में मानवीय शिक्षा संस्कारपूर्वक जागृति के लिए वांछित ज्ञान विवेक विज्ञान सहज संस्कार स्थापित किया जाना होता है।"
    ]
  },
  {
    "hindi": "राज्य व्यवस्था",
    "hinglish": "rajya vyavastha",
    "pageno": 160,
    "paribhasha": [
      "परिवार मूलक स्वराज्य विधि सहित सार्वभौम व्यवस्था सहज वैभव।"
    ]
  },
  {
    "hindi": "व्यवस्था",
    "hinglish": "vyavastha",
    "pageno": 179,
    "paribhasha": [
      "मानवत्व सहित वर्तमान परंपरा, वर्तमान में स्थिरता निश्चयता निरंतरता, सार्वभौम व्यवस्था परिवार मूलक दश सोपानीय व्यवस्था में भागीदारी, वर्तमान में विश्वास।",
      "मानवीय आचरण, संस्कृति एवं सभ्यता पूर्ण व्यवहार परंपरा वर्तमान में होना रहना।",
      "विधि के आशय को कार्यरूप में प्रदान करने हेतु प्रस्तुत परम्परा ही व्यवस्था है।",
      "व्यवहार गति में स्थायित्व, निरंतरता और वर्तमान में विश्वास।"
    ]
  },
  {
    "hindi": "व्यवस्थागत",
    "hinglish": "vyavasthagat",
    "pageno": 179,
    "paribhasha": [
      "व्यवस्था व्यवहार सुलभ होने के रूप में व्यवस्था मर्यादा में, व्यवस्थापूर्वक नियम, नियंत्रण, संतुलन रूप में।"
    ]
  },
  {
    "hindi": "व्यवस्था भेद",
    "hinglish": "vyavastha bhed",
    "pageno": 179,
    "paribhasha": [
      "दश सोपानीय विधि सहज।"
    ]
  },
  {
    "hindi": "व्यवहार व्यवस्था",
    "hinglish": "vyavahar vyavastha",
    "pageno": 180,
    "paribhasha": [
      "सार्वभौम व्यवस्था।"
    ]
  },
  {
    "hindi": "समग्र व्यवस्था",
    "hinglish": "samagra vyavastha",
    "pageno": 186,
    "paribhasha": [
      "जड़-चैतन्य प्रकृति में, से, के लिए समग्र व्यवस्था।"
    ]
  },
  {
    "hindi": "सम्यक व्यवस्था",
    "hinglish": "samyak vyavastha",
    "pageno": 192,
    "paribhasha": [
      "पूर्णता के अर्थ में की गई व्यवस्था, क्रिया पूर्णता, आचरण पूर्णता।"
    ]
  }
]

[
  {
    "hindi": "जागृति",
    "hinglish": "jagriti",
    "pageno": 75,
    "paribhasha": [
      "ज्ञान विवेक विज्ञान संपन्नता ज्ञान अर्थात् जीवन ज्ञान, अस्तित्व दर्शन ज्ञान, मानवीयपूर्ण आचरण ज्ञान की संयुक्त अभिव्यक्ति, जीवन लक्ष्य-मानव लक्ष्य को विवेचना सहित पहचानना।",
      "क्रियापूर्णता, सतर्कता, भ्रम से मुक्त जीवन, विकास परम सहज प्रकाशन।"
    ]
  },
  {
    "hindi": "जागृति क्रम",
    "hinglish": "jagriti kram",
    "pageno": 75,
    "paribhasha": [
      "भ्रान्त ज्ञानावस्था से भ्रान्ताभ्रान्त ज्ञानावस्था, भ्रान्ताभ्रान्त ज्ञानावस्था से निर्भ्रान्त ज्ञानावस्था का विकास।",
      "गणितवाद से गुणवाद, गुणवाद से कारणवाद, कारणवाद से जागृतिवाद।"
    ]
  },
  {
    "hindi": "जागृति पूर्णता",
    "hinglish": "jagriti purnata",
    "pageno": 77,
    "paribhasha": [
      "क्रियापूर्णता सहित आचरणपूर्णता, द़ृष्टापद जागृति, अखण्ड समाज सार्वभौम व्यवस्था में भागीदारी।",
      "गति का गन्तव्य, सजगता, सहजता।"
    ]
  },
  {
    "hindi": "जागृति सहज",
    "hinglish": "jagriti sahaj",
    "pageno": 76,
    "paribhasha": [
      "द़ृष्टा पद प्रतिष्ठा, जागृति सहज प्रमाण, अनुभव प्रमाण परंपरा, सार्वभौम व्यवस्था अखण्ड समाज में भागीदारी सहज वैभव।"
    ]
  },
  {
    "hindi": "जागृति पूर्वक",
    "hinglish": "jagriti purvak",
    "pageno": 76,
    "paribhasha": [
      "समझदारी सहज प्रमाण पूर्वक, ईमानदारी पूर्वक, जिम्मेदारी व भागीदारी पूर्वक किया गया कार्य व्यवहार।"
    ]
  },
  {
    "hindi": "जागृति गामी",
    "hinglish": "jagriti gami",
    "pageno": 76,
    "paribhasha": [
      "जागृति के लिए अध्ययन, अध्ययनशील।"
    ]
  },
  {
    "hindi": "जागृति पूर्ण क्षमता",
    "hinglish": "jagriti purn kshamata",
    "pageno": 76,
    "paribhasha": [
      "अखण्ड समाज सार्वभौम व्यवस्था सूत्र रूप में जीने का प्रमाण।"
    ]
  },
  {
    "hindi": "जागृति पूर्ण मानव",
    "hinglish": "jagriti purna manav",
    "pageno": 76,
    "paribhasha": [
      "मानव, देवमानव, दिव्यमानव उपकार विधि से जीना।"
    ]
  },
  {
    "hindi": "जागृति भाव",
    "hinglish": "jagriti bhav",
    "pageno": 76,
    "paribhasha": [
      "जानने मानने में निर्भ्रम, पहचान तथा निर्वाह।",
      "समाधान और प्रामाणिकता पूर्ण क्रियाकलाप।"
    ]
  },
  {
    "hindi": "जीवन जागृति",
    "hinglish": "jeevan jagriti",
    "pageno": 79,
    "paribhasha": [
      "श्रम का विश्राम, गति का गंतव्य, भ्रम मुक्ति, परम विकास, क्रिया पूर्णता, आचरण पूर्णता उसकी निरंतरता। मानव चेतना, देव मानव, दिव्य मानव।"
    ]
  },
  {
    "hindi": "जीवन जागृति क्रम",
    "hinglish": "jeevan jagriti kram",
    "pageno": 79,
    "paribhasha": [
      "अमानवीयता से मानवीयता, मानव से देव मानव, देव मानव से दिव्य मानवीयता की ओर गति।"
    ]
  },
  {
    "hindi": "विकास एवं जागृति पूर्णता",
    "hinglish": "vikas evam jagriti purnata",
    "pageno": 168,
    "paribhasha": [
      "जीवन पद, गठनपूर्णता, चैतन्य इकाई में क्रिया पूर्णता, आचरण पूर्णता।"
    ]
  }
]

